class AttemptFailure(RuntimeError):
    pass


@dataclass(frozen=True)
class PairPlan:
    round: int
    case_order: int
    clip: str
    mode: str
    role_order: str

    @property
    def case(self) -> str:
        return f"{self.clip}/{self.mode}"

    @property
    def pair_id(self) -> str:
        return f"round-{self.round}:{self.case}"


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat()


def sha256_file(path: pathlib.Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def write_json(path: pathlib.Path, value: Any, exclusive: bool = False) -> None:
    mode = "xb" if exclusive else "wb"
    with path.open(mode) as handle:
        handle.write((json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n").encode())
        handle.flush()
        os.fsync(handle.fileno())


def append_jsonl(path: pathlib.Path, value: Any) -> None:
    with path.open("ab") as handle:
        handle.write((json.dumps(value, sort_keys=True, ensure_ascii=False) + "\n").encode())
        handle.flush()
        os.fsync(handle.fileno())


def read_json(path: pathlib.Path, label: str) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise AttemptFailure(f"{label} is not readable JSON ({path}): {exc}") from exc
    if not isinstance(value, dict):
        raise AttemptFailure(f"{label} must be a JSON object: {path}")
    return value


def nested_value(doc: dict[str, Any], keys: tuple[str, ...]) -> Any:
    def visit(value: Any) -> Any:
        if isinstance(value, dict):
            for key in keys:
                child = value.get(key)
                if child is not None and isinstance(child, (str, int, float, bool)):
                    return child
            for child in value.values():
                found = visit(child)
                if found is not None:
                    return found
        elif isinstance(value, list):
            for child in value:
                found = visit(child)
                if found is not None:
                    return found
        return None
    return visit(doc)


def binary_identity(doc: dict[str, Any], label: str) -> tuple[str, str, dict[str, Any]]:
    for key in ("binary", "candidate_binary", "go_binary", "build"):
        obj = doc.get(key)
        if not isinstance(obj, dict):
            continue
        binary_path = obj.get("path") or obj.get("binary") or obj.get("go_binary_path")
        digest = obj.get("sha256") or obj.get("binary_sha256") or obj.get("go_binary_sha256")
        if isinstance(binary_path, str) and isinstance(digest, str):
            return binary_path, digest, obj
    binary_path = doc.get("binary_path") or doc.get("go_binary_path")
    digest = doc.get("binary_sha256") or doc.get("go_binary_sha256")
    if isinstance(binary_path, str) and isinstance(digest, str):
        return binary_path, digest, doc
    raise AttemptFailure(
        f"{label} manifest must bind a binary path and SHA-256 under binary, build, or top-level fields"
    )


def harness_sha(doc: dict[str, Any]) -> str | None:
    harnesses = doc.get("harnesses")
    if isinstance(harnesses, dict):
        for key in ("public_decoder", "decoder_fullclip", "public_fullclip", "decoder_harness"):
            record = harnesses.get(key)
            if isinstance(record, dict):
                value = record.get("sha256") or record.get("source_sha256")
                if isinstance(value, str):
                    return value
    for key in ("decoder_harness", "public_decoder_harness", "public_fullclip_harness"):
        record = doc.get(key)
        if isinstance(record, dict):
            value = record.get("sha256") or record.get("source_sha256")
            if isinstance(value, str):
                return value
    source_hashes = doc.get("source_sha256")
    if isinstance(source_hashes, dict) and isinstance(source_hashes.get(DECODER_HARNESS_REL), str):
        return source_hashes[DECODER_HARNESS_REL]
    return None


def declared_root(doc: dict[str, Any]) -> str | None:
    for key in ("worktree", "source_root", "source_worktree"):
        value = doc.get(key)
        if isinstance(value, str):
            return value
    project = doc.get("project")
    if isinstance(project, dict):
        for key in ("worktree", "source_root"):
            value = project.get(key)
            if isinstance(value, str):
                return value
    return None


def build_contract(doc: dict[str, Any], binary_record: dict[str, Any], label: str) -> dict[str, Any]:
    command = binary_record.get("build_command") or binary_record.get("command") or doc.get("build_command")
    if not isinstance(command, str) or "go test -c" not in command:
        raise AttemptFailure(f"{label} manifest must record its frozen go test -c build command")
    if str(PROJECT_ENV) not in command:
        raise AttemptFailure(f"{label} build command must use project-env")
    forbidden = ("-race", "-gcflags", "checkptr", "-cpuprofile", "-memprofile", "coverprofile")
    if any(token in command.lower() for token in forbidden):
        raise AttemptFailure(f"{label} build command appears instrumented: {command}")
    experiment = nested_value(doc, ("GOEXPERIMENT", "go_experiment", "goexperiment"))
    goos = nested_value(doc, ("GOOS", "goos"))
    goarch = nested_value(doc, ("GOARCH", "goarch"))
    for key, value, expected in (
        ("GOEXPERIMENT", experiment, "simd"),
        ("GOOS", goos, "darwin"),
        ("GOARCH", goarch, "arm64"),
    ):
        if value is None or str(value).lower() != expected:
            raise AttemptFailure(f"{label} manifest must record {key}={expected}, got {value!r}")
    for key, expected in (("buildmode", "exe"), ("compiler", "gc")):
        value = nested_value(doc, (key, key.lower()))
        if value is not None and str(value).lower() != expected:
            raise AttemptFailure(f"{label} manifest has {key}={value!r}, expected {expected!r}")
    flags = nested_value(doc, ("build_flags", "compiler_flags"))
    return {
        "build_command": command,
        "build_flags": flags,
        "toolchain": doc.get("toolchain"),
        "build": doc.get("build"),
        "build_info": doc.get("build_info"),
    }


def make_role_table(pairs_per_case: int) -> tuple[PairPlan, ...]:
    plans: list[PairPlan] = []
    for round_index in range(pairs_per_case):
        rotated = tuple(CASES[(i + round_index) % len(CASES)] for i in range(len(CASES)))
        for case_order, (clip, mode) in enumerate(rotated, start=1):
            case_index = CASES.index((clip, mode))
            first_order = "AB" if case_index % 2 == 0 else "BA"
            role_order = first_order if round_index % 2 == 0 else first_order[::-1]
            plans.append(PairPlan(round_index + 1, case_order, clip, mode, role_order))
    counts = {f"{clip}/{mode}": {"AB": 0, "BA": 0} for clip, mode in CASES}
    for plan in plans:
        counts[plan.case][plan.role_order] += 1
    if pairs_per_case == 3:
        if any(sorted(value.values()) != [1, 2] for value in counts.values()):
            raise AttemptFailure(f"screen needs opposite 2/1 role splits by case: {counts}")
        totals = {role: sum(value[role] for value in counts.values()) for role in ("AB", "BA")}
        if totals != {"AB": 6, "BA": 6}:
            raise AttemptFailure(f"screen must balance 6 AB/6 BA overall, got {totals}")
    elif any(value != {"AB": 5, "BA": 5} for value in counts.values()):
        raise AttemptFailure(f"10-pair confirmation must be 5 AB/5 BA per case: {counts}")
    return tuple(plans)


def planned_sample_order(table: tuple[PairPlan, ...]) -> list[dict[str, Any]]:
    return [
        {"round": plan.round, "case": plan.case, "role": role}
        for plan in table
        for role in plan.role_order
    ]


def process_table(raw: str) -> dict[int, tuple[int, int, str]]:
    table: dict[int, tuple[int, int, str]] = {}
    for line in raw.splitlines():
        fields = line.split(None, 3)
        if len(fields) != 4:
            raise AttemptFailure("process snapshot returned a malformed row")
        try:
            uid, pid, ppid = map(int, fields[:3])
        except ValueError as exc:
            raise AttemptFailure("process snapshot returned a non-integer id") from exc
        table[pid] = (uid, ppid, fields[3].strip())
    if not table:
        raise AttemptFailure("process snapshot was empty")
    return table


def uv_ancestry_depth(table: dict[int, tuple[int, int, str]]) -> int:
    depths: dict[int, int] = {}
    for start in table:
        if start in depths:
            continue
        chain: list[int] = []
        seen: set[int] = set()
        current = start
        while current in table and current not in depths and current not in seen:
            seen.add(current)
            chain.append(current)
            current = table[current][1]
        depth = depths.get(current, 0)
        for pid in reversed(chain):
            if table[pid][2].lower() == "uv":
                depth += 1
            depths[pid] = depth
    return max((depths.get(pid, 0) for pid, row in table.items() if row[2].lower() == "uv"), default=0)


class Runner:
    def __init__(self, args: argparse.Namespace):
        self.args = args
        self.out = args.output_dir.resolve()
        self.runner_script = pathlib.Path(__file__).resolve()
        self.runner_sha256_before = sha256_file(self.runner_script)
        self.runner_copy = self.out / "inputs" / "run-screen.py"
        self.started_utc = utc_now()
        self.current_stage = "startup"
        self.event_path = self.out / "subprocess-events.jsonl"
        self.resource_path = self.out / "resource-snapshots.jsonl"
        self.metadata_path = self.out / "metadata-commands.jsonl"
        self.rows_path = self.out / "rows.jsonl"
        self.preflights: list[dict[str, Any]] = []
        self.rows: list[dict[str, Any]] = []
        self.actual_order: list[dict[str, Any]] = []
        self.invocation_index = 0
        self.limits: dict[str, int] = {}
        self.mode = args.mode
        self.pairs_per_case = 3 if self.mode == "screen" else 10
        self.role_table: tuple[PairPlan, ...] = make_role_table(self.pairs_per_case)

    def metadata_command(self, label: str, argv: list[str], cwd: pathlib.Path | None = None) -> str:
        start = utc_now()
        tick = time.monotonic()
        try:
            result = subprocess.run(
                argv, cwd=str(cwd) if cwd else None, capture_output=True, text=True,
                timeout=30, check=False,
            )
            record = {
                "label": label, "argv": argv, "cwd": str(cwd) if cwd else None,
                "started_utc": start, "elapsed_seconds": time.monotonic() - tick,
                "exit_code": result.returncode, "stdout": result.stdout, "stderr": result.stderr,
            }
            append_jsonl(self.metadata_path, record)
            if result.returncode != 0:
                raise AttemptFailure(f"{label} exited {result.returncode}: {result.stderr.strip()}")
            return result.stdout.strip()
        except (OSError, subprocess.TimeoutExpired) as exc:
            append_jsonl(self.metadata_path, {
                "label": label, "argv": argv, "cwd": str(cwd) if cwd else None,
                "started_utc": start, "elapsed_seconds": time.monotonic() - tick, "error": str(exc),
            })
            raise AttemptFailure(f"{label} failed: {exc}") from exc

    def git_observation(self, variant: dict[str, Any], when: str) -> dict[str, str]:
        root = variant["source_root"]
        common = self.metadata_command(
            f"{variant['name']}-git-common-dir-{when}", ["git", "rev-parse", "--git-common-dir"], root
        )
        common_path = pathlib.Path(common)
        if not common_path.is_absolute():
            common_path = (root / common_path).resolve()
        return {
            "head": self.metadata_command(f"{variant['name']}-git-head-{when}", ["git", "rev-parse", "HEAD"], root),
            "common_dir": str(common_path.resolve()),
            "status_porcelain": self.metadata_command(
                f"{variant['name']}-git-status-{when}", ["git", "status", "--porcelain=v1"], root
            ),
        }

    def source_manifest_hashes(self, doc: dict[str, Any], root: pathlib.Path, label: str) -> dict[str, str]:
        hashes = doc.get("source_sha256") or doc.get("source_files_sha256")
        observed: dict[str, str] = {}
        if not isinstance(hashes, dict):
            return observed
        for rel, expected in hashes.items():
            if not isinstance(rel, str) or not isinstance(expected, str):
                raise AttemptFailure(f"{label} source hash entry is malformed: {rel!r}")
            relative = pathlib.PurePosixPath(rel)
            if relative.is_absolute() or ".." in relative.parts:
                raise AttemptFailure(f"{label} source path escapes worktree: {rel}")
            path = (root / pathlib.Path(*relative.parts)).resolve()
            try:
                path.relative_to(root)
            except ValueError as exc:
                raise AttemptFailure(f"{label} source path escapes worktree: {rel}") from exc
            if not path.is_file():
                raise AttemptFailure(f"{label} manifest source file missing: {rel}")
            actual = sha256_file(path)
            if actual != expected:
                raise AttemptFailure(f"{label} source hash mismatch for {rel}: {actual} != {expected}")
            observed[rel] = actual
        return observed

    def variant(self, name: str, binary: pathlib.Path, manifest_path: pathlib.Path,
                source_root: pathlib.Path) -> dict[str, Any]:
        manifest_path = manifest_path.resolve()
        source_root = source_root.resolve()
        binary = binary.resolve()
        doc = read_json(manifest_path, f"{name} manifest")
        declared_path, digest, binary_record = binary_identity(doc, name)
        build = build_contract(doc, binary_record, name)
        if not binary.is_file() or not os.access(binary, os.X_OK):
            raise AttemptFailure(f"{name} frozen binary missing/not executable: {binary}")
        declared_binary = pathlib.Path(declared_path)
        if declared_binary.is_absolute() and declared_binary.resolve() != binary:
            raise AttemptFailure(f"{name} CLI binary differs from manifest: {binary} != {declared_binary.resolve()}")
        if not manifest_path.is_file() or not source_root.is_dir():
            raise AttemptFailure(f"{name} manifest/source root missing")
        root_declared = declared_root(doc)
        if root_declared and pathlib.Path(root_declared).resolve() != source_root:
            raise AttemptFailure(f"{name} source root differs from manifest: {source_root} != {root_declared}")
        declared_harness = harness_sha(doc)
        harness_path = source_root / DECODER_HARNESS_REL
        if not harness_path.is_file():
            raise AttemptFailure(f"{name} source root lacks {DECODER_HARNESS_REL}")
        actual_harness = sha256_file(harness_path)
        if actual_harness != EXPECTED_DECODER_HARNESS_SHA256:
            raise AttemptFailure(
                f"{name} decoder harness changed: {actual_harness} != {EXPECTED_DECODER_HARNESS_SHA256}"
            )
        if declared_harness and declared_harness != actual_harness:
            raise AttemptFailure(f"{name} manifest decoder harness hash disagrees with its source root")
        source_hashes = self.source_manifest_hashes(doc, source_root, name)
        actual_binary = sha256_file(binary)
        if actual_binary != digest:
            raise AttemptFailure(f"{name} binary hash mismatch: {actual_binary} != manifest {digest}")
        stat = binary.stat()
        source_identity = {
            key: doc[key]
            for key in ("head", "tree", "worktree_clean", "worktree", "branch")
            if key in doc
        }
        return {
            "name": name,
            "binary": binary,
            "binary_sha256": actual_binary,
            "binary_stat_before": {"size_bytes": stat.st_size, "mtime_ns": stat.st_mtime_ns},
            "manifest": manifest_path,
            "manifest_sha256": sha256_file(manifest_path),
            "manifest_doc": doc,
            "declared_binary_path": declared_path,
            "source_root": source_root,
            "declared_source_root": root_declared,
            "declared_harness_sha256": declared_harness,
            "actual_harness_sha256": actual_harness,
            "source_hashes_verified": source_hashes,
            "frozen_build_source_identity_from_manifest": source_identity,
            "build_contract": build,
        }

    def snapshot(self, stage: str, enforce: bool = True) -> dict[str, Any]:
        command = ["/bin/ps", "-A", "-o", "uid=,pid=,ppid=,ucomm="]
        started = utc_now()
        tick = time.monotonic()
        try:
            proc = subprocess.run(command, capture_output=True, text=True, timeout=30, check=False)
            ps_record = {
                "ps_command": command,
                "ps_started_utc": started,
                "ps_elapsed_seconds": time.monotonic() - tick,
                "ps_exit_code": proc.returncode,
                "ps_stderr": proc.stderr,
            }
            table = process_table(proc.stdout) if proc.returncode == 0 else {}
        except (OSError, subprocess.TimeoutExpired, AttemptFailure) as exc:
            table = {}
            ps_record = {
                "ps_command": command,
                "ps_started_utc": started,
                "ps_elapsed_seconds": time.monotonic() - tick,
                "ps_error": str(exc),
            }
        row: dict[str, Any] = {
            "stage": stage,
            "captured_utc": utc_now(),
            "free_disk_bytes": shutil.disk_usage(self.out).free,
            "minimum_free_bytes": MIN_FREE_BYTES,
            "uid": os.getuid(),
            "cpu_count": os.cpu_count(),
            "load_average_1_5_15": list(os.getloadavg()) if hasattr(os, "getloadavg") else None,
            **ps_record,
        }
        problems: list[str] = []
        if table:
            uid_count = sum(1 for values in table.values() if values[0] == os.getuid())
            system_count = len(table)
            uv_count = sum(1 for values in table.values() if values[2].lower() == "uv")
            uv_depth = uv_ancestry_depth(table)
            row.update({
                "status": "PASS",
                "uid_process_count": uid_count,
                "uid_process_limit": self.limits.get("user"),
                "uid_headroom": self.limits.get("user", uid_count) - uid_count,
                "minimum_uid_headroom": MIN_USER_HEADROOM,
                "system_process_count": system_count,
                "system_process_limit": self.limits.get("system"),
                "system_headroom": self.limits.get("system", system_count) - system_count,
                "minimum_system_headroom": MIN_SYSTEM_HEADROOM,
                "uv_process_count": uv_count,
                "max_uv_ancestry_depth": uv_depth,
                "maximum_allowed_uv_ancestry_depth": MAX_UV_ANCESTRY_DEPTH,
            })
            if row["uid_headroom"] < MIN_USER_HEADROOM:
                problems.append("per-user process headroom below minimum")
            if row["system_headroom"] < MIN_SYSTEM_HEADROOM:
                problems.append("system process headroom below minimum")
            if uv_depth > MAX_UV_ANCESTRY_DEPTH:
                problems.append("recursive uv ancestry exceeds maximum")
        else:
            row["status"] = "ERROR"
            problems.append("process snapshot unavailable")
        if row["free_disk_bytes"] < MIN_FREE_BYTES:
            problems.append("free disk below minimum")
        if problems:
            row["status"] = "FAIL"
            row["problems"] = problems
        append_jsonl(self.resource_path, row)
        if problems and enforce:
            raise AttemptFailure(f"resource observation failed at {stage}: {', '.join(problems)}; no processes were killed")
        return row

    def run_test_binary(self, variant: dict[str, Any], label: str, test_args: list[str],
                        extra_env: dict[str, str] | None = None,
                        pair: PairPlan | None = None, role: str | None = None) -> tuple[float, pathlib.Path]:
        self.current_stage = label
        self.invocation_index += 1
        agent = f"{self.args.agent_id}-{self.invocation_index:03d}-{variant['name']}"
        env_record = {
            "CODEX_AGENT_ID": agent,
            "CODEX_PROJECT_CACHE_ROOT": str(PROJECT_CACHE_ROOT),
            "GOEXPERIMENT": "simd",
            "GOMAXPROCS": "1",
            "GOGC": "100",
            "GOAV1_BENCH_CORPUS_DIR": str(self.args.corpus_dir.resolve()),
        }
        if extra_env:
            env_record.update(extra_env)
        env = os.environ.copy()
        env.update(env_record)
        command = [str(PROJECT_ENV), str(variant["binary"]), *test_args]
        log = self.out / f"{label}.log"
        before = self.snapshot(f"{label}:before")
        started_utc = utc_now()
        tick = time.monotonic()
        try:
            proc = subprocess.run(
                command, cwd=str(variant["source_root"]), env=env,
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                timeout=COMMAND_TIMEOUT_SECONDS, check=False,
            )
            raw = proc.stdout
            exit_code = proc.returncode
            timeout_error = None
        except subprocess.TimeoutExpired as exc:
            raw = exc.stdout or b""
            if isinstance(raw, str):
                raw = raw.encode("utf-8", errors="replace")
            exit_code = None
            timeout_error = f"timeout after {COMMAND_TIMEOUT_SECONDS}s"
        except OSError as exc:
            raw = f"spawn failed: {exc}\n".encode()
            exit_code = None
            timeout_error = str(exc)
        elapsed = time.monotonic() - tick
        log.write_bytes(raw)
        with log.open("rb") as handle:
            os.fsync(handle.fileno())
        # Preserve the completed subprocess event even when the post-run host
        # observation fails a guard. The run is then marked incomplete, but its
        # command, log, exit status, and post-run snapshot remain auditable.
        after = self.snapshot(f"{label}:after", enforce=False)
        event = {
            "invocation_index": self.invocation_index,
            "label": label,
            "kind": "test_binary",
            "variant": variant["name"],
            "role": role,
            "pair": asdict(pair) if pair else None,
            "command": command,
            "cwd": str(variant["source_root"]),
            "environment": env_record,
            "started_utc": started_utc,
            "elapsed_wall_seconds": elapsed,
            "exit_code": exit_code,
            "timeout_error": timeout_error,
            "resource_before": before["stage"],
            "resource_after": after["stage"],
            "log_path": str(log),
            "log_sha256": sha256_file(log),
        }
        append_jsonl(self.event_path, event)
        if after["status"] != "PASS":
            raise AttemptFailure(
                f"resource observation failed at {label}:after: "
                f"{', '.join(after.get('problems', []))}; no processes were killed"
            )
        if exit_code != 0:
            raise AttemptFailure(f"{label} exited {exit_code}: {timeout_error or log}")
        return elapsed, log

    def run_preflight(self, variant: dict[str, Any]) -> None:
        label = f"preflight-{variant['name']}-md5-workers1"
        elapsed, log = self.run_test_binary(
            variant, label,
            ["-test.run=^TestPublicDecoderFullClipCorpusMD5$", "-test.count=1", "-test.v"],
            {"GOAV1_PUBLIC_FULLCLIP": "1"},
        )
        output = log.read_text(encoding="utf-8", errors="replace")
        marker = "public decoder MD5 preflight passed: clips=18 frames=864 workers=1"
        if output.count(marker) != 1 or not output.rstrip().endswith("PASS"):
            raise AttemptFailure(f"{variant['name']} 18-clip MD5 preflight failed: {log}")
        self.preflights.append({
            "variant": variant["name"],
            "binary_sha256": variant["binary_sha256"],
            "elapsed_wall_seconds": elapsed,
            "log_path": str(log),
            "log_sha256": sha256_file(log),
            "expected_marker": marker,
            "exit_code": 0,
        })

    def parse_benchmark(self, variant: dict[str, Any], pair: PairPlan, role: str,
                        elapsed: float, log: pathlib.Path) -> dict[str, Any]:
        output = log.read_text(encoding="utf-8", errors="replace")
        expected_name = f"BenchmarkPublicDecoderFullClip/{pair.clip}/{pair.mode}"
        lines = []
        for line in output.splitlines():
            match = BENCH_LINE.match(line)
            if match and line.split()[0] == expected_name:
                lines.append(line.strip())
        if len(lines) != 1:
            raise AttemptFailure(f"expected exactly one {expected_name} benchmark line in {log}, got {len(lines)}")
        fields = lines[0].split()
        if (
            len(fields) != 10 or fields[1] != str(N_OPS) or fields[3] != "ns/op"
            or fields[5] != "frames/op" or fields[7] != "B/op" or fields[9] != "allocs/op"
        ):
            raise AttemptFailure(f"benchmark output contract mismatch: {lines[0]!r}")
        if Decimal(fields[4]) != Decimal(FRAMES_PER_OP):
            raise AttemptFailure(f"expected {FRAMES_PER_OP} frames/op: {lines[0]!r}")
        if not output.rstrip().endswith("PASS"):
            raise AttemptFailure(f"benchmark output did not end in PASS: {log}")
        try:
            ns_op, bytes_op, allocs_op = float(fields[2]), int(fields[6]), int(fields[8])
        except ValueError as exc:
            raise AttemptFailure(f"cannot parse benchmark metrics: {lines[0]!r}") from exc
        return {
            **asdict(pair),
            "case": pair.case,
            "pair_id": pair.pair_id,
            "role_order": pair.role_order,
            "role": role,
            "variant": variant["name"],
            "binary": str(variant["binary"]),
            "binary_sha256": variant["binary_sha256"],
            "selector": f"^BenchmarkPublicDecoderFullClip$/{pair.clip}$/{pair.mode}$",
            "command": [
                str(PROJECT_ENV), str(variant["binary"]),
                "-test.run=^$",
                f"-test.bench=^BenchmarkPublicDecoderFullClip$/{pair.clip}$/{pair.mode}$",
                f"-test.benchtime={N_OPS}x", "-test.count=1", "-test.benchmem",
            ],
            "elapsed_wall_seconds": elapsed,
            "reported_benchmark_line": lines[0],
            "operations": N_OPS,
            "frames_per_op": FRAMES_PER_OP,
            "ns_per_op": ns_op,
            "bytes_per_op": bytes_op,
            "allocs_per_op": allocs_op,
            "log_path": str(log),
            "log_sha256": sha256_file(log),
        }

    def run_samples(self) -> None:
        variants = {variant["name"]: variant for variant in self.variants}
        role_variant = {"A": "baseline", "B": "candidate"}
        for pair in self.role_table:
            for role in pair.role_order:
                variant = variants[role_variant[role]]
                label = (
                    f"round-{pair.round:02d}-case-{pair.case_order}-"
                    f"{pair.clip}-{pair.mode}-role-{role}"
                )
                selector = f"^BenchmarkPublicDecoderFullClip$/{pair.clip}$/{pair.mode}$"
                test_args = [
                    "-test.run=^$",
                    f"-test.bench={selector}",
                    f"-test.benchtime={N_OPS}x",
                    "-test.count=1",
                    "-test.benchmem",
                ]
                elapsed, log = self.run_test_binary(
                    variant, label, test_args, pair=pair, role=role
                )
                row = self.parse_benchmark(variant, pair, role, elapsed, log)
                self.rows.append(row)
                append_jsonl(self.rows_path, row)
                self.actual_order.append({"round": pair.round, "case": pair.case, "role": role})

    def role_balance(self) -> dict[str, Any]:
        per_case = {f"{clip}/{mode}": {"AB": 0, "BA": 0} for clip, mode in CASES}
        for pair in self.role_table:
            per_case[pair.case][pair.role_order] += 1
        totals = {role: sum(value[role] for value in per_case.values()) for role in ("AB", "BA")}
        return {"per_case": per_case, "totals": totals}

    def summarize(self) -> dict[str, Any]:
        expected = planned_sample_order(self.role_table)
        if self.actual_order != expected:
            raise AttemptFailure(f"saved execution order differs from shared role table: {self.actual_order} != {expected}")
        by_pair: dict[str, dict[str, dict[str, Any]]] = {}
        for row in self.rows:
            roles = by_pair.setdefault(row["pair_id"], {})
            if row["role"] in roles:
                raise AttemptFailure(f"duplicate role row for {row['pair_id']} {row['role']}")
            roles[row["role"]] = row
        if len(by_pair) != self.pairs_per_case * len(CASES):
            raise AttemptFailure(f"expected {self.pairs_per_case * len(CASES)} pairs, got {len(by_pair)}")
        if any(set(roles) != {"A", "B"} for roles in by_pair.values()):
            raise AttemptFailure("a pair lacks baseline or candidate row")

        results: dict[str, Any] = {}
        for clip, mode in CASES:
            case = f"{clip}/{mode}"
            selected = [
                (pair_id, roles) for pair_id, roles in by_pair.items()
                if roles["A"]["case"] == case
            ]
            selected.sort(key=lambda item: int(item[0].split(":", 1)[0].removeprefix("round-")))
            a = [roles["A"] for _, roles in selected]
            b = [roles["B"] for _, roles in selected]
            pair_ratios = [left["ns_per_op"] / right["ns_per_op"] for left, right in zip(a, b)]
            results[case] = {
                "pair_count": len(selected),
                "baseline_ns_per_op_median": statistics.median(row["ns_per_op"] for row in a),
                "candidate_ns_per_op_median": statistics.median(row["ns_per_op"] for row in b),
                "baseline_over_candidate_ratio_of_medians": (
                    statistics.median(row["ns_per_op"] for row in a)
                    / statistics.median(row["ns_per_op"] for row in b)
                ),
                "paired_baseline_over_candidate_ratios": pair_ratios,
                "paired_ratio_median": statistics.median(pair_ratios),
                "baseline_bytes_per_op_median": statistics.median(row["bytes_per_op"] for row in a),
                "candidate_bytes_per_op_median": statistics.median(row["bytes_per_op"] for row in b),
                "baseline_allocs_per_op_median": statistics.median(row["allocs_per_op"] for row in a),
                "candidate_allocs_per_op_median": statistics.median(row["allocs_per_op"] for row in b),
                "all_pairs": [
                    {
                        "pair_id": pair_id,
                        "role_order": roles["A"]["role_order"],
                        "baseline_ns_per_op": roles["A"]["ns_per_op"],
                        "candidate_ns_per_op": roles["B"]["ns_per_op"],
                        "baseline_over_candidate_ratio": roles["A"]["ns_per_op"] / roles["B"]["ns_per_op"],
                        "baseline_bytes_per_op": roles["A"]["bytes_per_op"],
                        "candidate_bytes_per_op": roles["B"]["bytes_per_op"],
                        "baseline_allocs_per_op": roles["A"]["allocs_per_op"],
                        "candidate_allocs_per_op": roles["B"]["allocs_per_op"],
                    }
                    for pair_id, roles in selected
                ],
            }
        return {
            "schema": "goav1-public-decoder-paired-screen-summary-v1",
            "mode": self.mode,
            "screen_only": self.mode == "screen",
            "pairs_per_case": self.pairs_per_case,
            "sample_rows": len(self.rows),
            "operations_per_sample": N_OPS,
            "frames_per_operation": FRAMES_PER_OP,
            "case_results": results,
            "role_balance": self.role_balance(),
            "actual_sample_order": self.actual_order,
            "interpretation": "Descriptive only; all planned samples are included, with no selective exclusion or significance claim.",
        }

    def write_summary_markdown(self, summary: dict[str, Any]) -> None:
        lines = [
            f"# Public decoder {self.mode}: frozen baseline vs candidate",
            "",
            f"Pairs per case: {self.pairs_per_case}; operations per process: {N_OPS}; frames per operation: {FRAMES_PER_OP}.",
            "",
            "| Case | Baseline median (ms/op) | Candidate median (ms/op) | Baseline/candidate | Baseline B/op | Candidate B/op | Baseline allocs/op | Candidate allocs/op |",
            "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
        for case, result in summary["case_results"].items():
            lines.append(
                f"| {case} | {result['baseline_ns_per_op_median'] / 1e6:.3f} | "
                f"{result['candidate_ns_per_op_median'] / 1e6:.3f} | "
                f"{result['baseline_over_candidate_ratio_of_medians']:.4f}× | "
                f"{result['baseline_bytes_per_op_median']} | {result['candidate_bytes_per_op_median']} | "
                f"{result['baseline_allocs_per_op_median']} | {result['candidate_allocs_per_op_median']} |"
            )
        lines.extend([
            "",
            "All raw rows are retained. The same role table drove execution and appears in the manifest. Screen mode assigns each case a 2/1 AB/BA split with opposite splits across cases and 6 AB/6 BA overall. Confirmation mode has five AB and five BA per case. Case order rotates each round.",
            "",
            "Results are descriptive; there is no selective sample exclusion or significance claim. Cold-fresh includes NewDecoderFromIVF, decode, and close. Warm-reset reuses one single-worker decoder. Each operation covers 48 frames.",
            "",
            "## Pair-level samples",
            "",
        ])
        for case, result in summary["case_results"].items():
            lines.extend([
                f"### {case}",
                "",
                "| Pair | Role order | Baseline (ms/op) | Candidate (ms/op) | Baseline/candidate |",
                "| --- | --- | ---: | ---: | ---: |",
            ])
            for row in result["all_pairs"]:
                lines.append(
                    f"| {row['pair_id']} | {row['role_order']} | {row['baseline_ns_per_op'] / 1e6:.3f} | "
                    f"{row['candidate_ns_per_op'] / 1e6:.3f} | {row['baseline_over_candidate_ratio']:.4f}× |"
                )
            lines.append("")
        (self.out / "summary.md").write_text("\n".join(lines), encoding="utf-8")

    def verify_final_identity(self) -> None:
        if sha256_file(self.runner_script) != self.runner_sha256_before:
            raise AttemptFailure("runner source changed during attempt")
        if not self.runner_copy.is_file() or sha256_file(self.runner_copy) != self.runner_sha256_before:
            raise AttemptFailure("saved runner copy does not match the executed runner source")
        for variant in self.variants:
            if sha256_file(variant["binary"]) != variant["binary_sha256"]:
                raise AttemptFailure(f"{variant['name']} binary SHA changed during attempt")
            stat = variant["binary"].stat()
            if {"size_bytes": stat.st_size, "mtime_ns": stat.st_mtime_ns} != variant["binary_stat_before"]:
                raise AttemptFailure(f"{variant['name']} binary stat changed during attempt")
            if sha256_file(variant["manifest"]) != variant["manifest_sha256"]:
                raise AttemptFailure(f"{variant['name']} manifest changed during attempt")
            observed_sources = self.source_manifest_hashes(
                variant["manifest_doc"], variant["source_root"], variant["name"]
            )
            if observed_sources != variant["source_hashes_verified"]:
                raise AttemptFailure(f"{variant['name']} declared source files changed during attempt")

    def checksum_file(self) -> None:
        checksum = self.out / "artifact-SHA256SUMS.txt"
        lines = []
        for path in sorted(path for path in self.out.rglob("*") if path.is_file() and path != checksum):
            lines.append(f"{sha256_file(path)}  {path.relative_to(self.out)}")
        checksum.write_text("\n".join(lines) + "\n", encoding="utf-8")

    def fail(self, exc: Exception) -> None:
        if not self.out.exists():
            return
        payload = {
            "status": "FAILED_INCOMPLETE",
            "started_utc": self.started_utc,
            "failed_utc": utc_now(),
            "stage": self.current_stage,
            "failure": str(exc),
            "exception_type": type(exc).__name__,
            "mode": self.mode,
            "no_resume": True,
            "disposition": "Preserve the entire attempt; never resume or selectively exclude samples.",
            "planned_role_table": [asdict(plan) for plan in self.role_table],
            "actual_sample_order": self.actual_order,
            "completed_preflights": self.preflights,
            "completed_rows": len(self.rows),
            "resource_snapshot_path": str(self.resource_path),
            "subprocess_events_path": str(self.event_path),
        }
        try:
            write_json(self.out / "FAILED_INCOMPLETE.json", payload, exclusive=True)
        except (OSError, FileExistsError):
            pass

    def run(self) -> dict[str, Any]:
        if self.mode == "confirmation" and not self.args.root_authorized:
            raise AttemptFailure("confirmation mode requires --root-authorized after explicit parent approval")
        if self.mode == "screen" and self.args.root_authorized:
            raise AttemptFailure("--root-authorized is only for confirmation mode")
        if not self.args.output_dir.is_absolute():
            raise AttemptFailure("--output-dir must be an absolute fresh path")
        if self.args.output_dir.exists():
            raise AttemptFailure(f"refusing to overwrite existing output directory: {self.args.output_dir}")
        if not PROJECT_ENV.is_file() or not os.access(PROJECT_ENV, os.X_OK):
            raise AttemptFailure(f"project-env is unavailable: {PROJECT_ENV}")
        if ".codex/worktrees" in str(PROJECT_CACHE_ROOT):
            raise AttemptFailure("project cache path contains invalid .codex/worktrees component")
        if not PROJECT_CACHE_ROOT.is_absolute():
            raise AttemptFailure("project cache root must be absolute")
        if not self.args.corpus_dir.is_absolute() or not self.args.corpus_dir.is_dir():
            raise AttemptFailure("corpus directory must be absolute and present")
        clips = sorted(self.args.corpus_dir.glob("*.ivf"))
        if len(clips) != 18:
            raise AttemptFailure(f"expected 18 IVF clips, found {len(clips)}")
        for clip in clips:
            if not clip.with_suffix(".md5").is_file():
                raise AttemptFailure(f"missing sidecar for {clip.name}")

        self.out.mkdir(parents=True)
        (self.out / "inputs").mkdir()
        shutil.copyfile(self.runner_script, self.runner_copy)
        if sha256_file(self.runner_copy) != self.runner_sha256_before:
            raise AttemptFailure("could not pin an exact copy of the executed runner")
        baseline = self.variant("baseline", self.args.baseline_binary, self.args.baseline_manifest, self.args.baseline_source_root)
        candidate = self.variant("candidate", self.args.candidate_binary, self.args.candidate_manifest, self.args.candidate_source_root)
        self.variants = [baseline, candidate]
        for variant in self.variants:
            shutil.copyfile(variant["manifest"], self.out / "inputs" / f"{variant['name']}-manifest.json")

        self.source_before = {variant["name"]: self.git_observation(variant, "before") for variant in self.variants}
        common_dirs = {value["common_dir"] for value in self.source_before.values()}
        if len(common_dirs) != 1:
            raise AttemptFailure(f"variant roots do not share the same Git common directory: {self.source_before}")
        if self.source_before["baseline"]["common_dir"] != self.source_before["candidate"]["common_dir"]:
            raise AttemptFailure("baseline/candidate project cache scopes differ")

        self.limits["user"] = int(self.metadata_command(
            "per-user-process-limit", ["/usr/sbin/sysctl", "-n", "kern.maxprocperuid"]
        ).splitlines()[-1].split()[-1])
        self.limits["system"] = int(self.metadata_command(
            "system-process-limit", ["/usr/sbin/sysctl", "-n", "kern.maxproc"]
        ).splitlines()[-1].split()[-1])

        environment = {
            "captured_utc": utc_now(),
            "host": platform.uname()._asdict(),
            "python": sys.version,
            "python_executable": sys.executable,
            "cpu_count": os.cpu_count(),
            "load_average_at_setup": list(os.getloadavg()) if hasattr(os, "getloadavg") else None,
            "project_env": str(PROJECT_ENV),
            "project_cache_root": str(PROJECT_CACHE_ROOT),
            "git_common_dir": next(iter(common_dirs)),
            "project_cache_policy": "shared project root; project-env invoked with cwd inside each Git worktree",
            "go_environment": {
                "GOEXPERIMENT": "simd", "GOMAXPROCS": "1", "GOGC": "100",
                "GOAV1_BENCH_CORPUS_DIR": str(self.args.corpus_dir.resolve()),
            },
            "resource_guard": {
                "minimum_free_bytes": MIN_FREE_BYTES,
                "minimum_uid_process_headroom": MIN_USER_HEADROOM,
                "minimum_system_process_headroom": MIN_SYSTEM_HEADROOM,
                "maximum_uv_ancestry_depth": MAX_UV_ANCESTRY_DEPTH,
                "policy": "observe host contention and stop before further work if thresholds fail; never kill processes",
            },
        }
        self.environment = environment
        self.startup_snapshots = []
        for index in range(STARTUP_SNAPSHOTS):
            self.startup_snapshots.append(self.snapshot(f"startup-{index + 1}-of-{STARTUP_SNAPSHOTS}"))
            if index + 1 < STARTUP_SNAPSHOTS:
                time.sleep(STARTUP_SNAPSHOT_GAP_SECONDS)

        plan = {
            "schema": "goav1-public-decoder-screen-plan-v1",
            "status": "PREPARED",
            "mode": self.mode,
            "screen_only": self.mode == "screen",
            "pairs_per_case": self.pairs_per_case,
            "operations_per_sample": N_OPS,
            "frames_per_operation": FRAMES_PER_OP,
            "worker_count": 1,
            "case_order_rotates": True,
            "cases": [{"clip": clip, "mode": mode} for clip, mode in CASES],
            "role_table": [asdict(plan) for plan in self.role_table],
            "expected_sample_order": planned_sample_order(self.role_table),
            "role_balance": self.role_balance(),
            "preflight_plan": "baseline then candidate; TestPublicDecoderFullClipCorpusMD5, 18 clips and 864 frames, one worker",
            "variants": [
                {
                    "name": variant["name"],
                    "binary_path": str(variant["binary"]),
                    "binary_sha256": variant["binary_sha256"],
                    "binary_stat_before": variant["binary_stat_before"],
                    "manifest_path": str(variant["manifest"]),
                    "manifest_sha256": variant["manifest_sha256"],
                    "source_root": str(variant["source_root"]),
                    "manifest_source_root": variant["declared_source_root"],
                    "frozen_build_source_identity_from_manifest": variant["frozen_build_source_identity_from_manifest"],
                    "decoder_harness_sha256": variant["actual_harness_sha256"],
                    "manifest_decoder_harness_sha256": variant["declared_harness_sha256"],
                    "source_hashes_verified": variant["source_hashes_verified"],
                    "build_contract": variant["build_contract"],
                    "manifest": variant["manifest_doc"],
                }
                for variant in self.variants
            ],
            "source_observations_before": self.source_before,
            "environment": environment,
            "corpus_dir": str(self.args.corpus_dir.resolve()),
            "corpus_clips": [path.name for path in clips],
            "output_dir": str(self.out),
            "started_utc": self.started_utc,
            "runner_source_path": str(self.runner_script),
            "runner_source_sha256": self.runner_sha256_before,
            "runner_copy_path": str(self.runner_copy),
        }
        write_json(self.out / "plan.json", plan, exclusive=True)

        for variant in self.variants:
            self.run_preflight(variant)
        self.run_samples()
        self.verify_final_identity()
        self.source_after = {variant["name"]: self.git_observation(variant, "after") for variant in self.variants}
        self.snapshot("final-completion")
        summary = self.summarize()
        write_json(self.out / "summary.json", summary, exclusive=True)
        self.write_summary_markdown(summary)
        manifest = {
            "schema": "goav1-public-decoder-screen-run-v1",
            "status": "COMPLETE",
            "mode": self.mode,
            "screen_only": self.mode == "screen",
            "started_utc": self.started_utc,
            "finished_utc": utc_now(),
            "plan_path": str(self.out / "plan.json"),
            "preflights": self.preflights,
            "rows_path": str(self.rows_path),
            "rows_sha256": sha256_file(self.rows_path),
            "actual_sample_order": self.actual_order,
            "role_balance": self.role_balance(),
            "case_summary": summary["case_results"],
            "source_observations_after": self.source_after,
            "subprocess_event_count": sum(1 for _ in self.event_path.open("rb")),
            "resource_snapshot_count": sum(1 for _ in self.resource_path.open("rb")),
            "metadata_command_count": sum(1 for _ in self.metadata_path.open("rb")),
            "environment": self.environment,
            "output_dir": str(self.out),
            "selective_sample_exclusion": False,
            "runner_source_path": str(self.runner_script),
            "runner_source_sha256_before": self.runner_sha256_before,
            "runner_source_sha256_after": sha256_file(self.runner_script),
            "runner_copy_path": str(self.runner_copy),
            "runner_copy_sha256": sha256_file(self.runner_copy),
        }
        write_json(self.out / "manifest.json", manifest, exclusive=True)
        self.checksum_file()
        write_json(self.out / "COMPLETE.json", {
            "status": "COMPLETE",
            "completed_utc": utc_now(),
            "manifest": str(self.out / "manifest.json"),
            "summary": str(self.out / "summary.json"),
        }, exclusive=True)
        return summary


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--mode", choices=("screen", "confirmation"), required=True)
    parser.add_argument("--root-authorized", action="store_true",
                        help="confirmation only: require explicit parent authorization")
    parser.add_argument("--baseline-binary", type=pathlib.Path, default=BASELINE_BINARY)
    parser.add_argument("--baseline-manifest", type=pathlib.Path, default=BASELINE_IDENTITY)
    parser.add_argument("--baseline-source-root", type=pathlib.Path, required=True)
    parser.add_argument("--candidate-binary", type=pathlib.Path, required=True)
    parser.add_argument("--candidate-manifest", type=pathlib.Path, required=True)
    parser.add_argument("--candidate-source-root", type=pathlib.Path, required=True)
    parser.add_argument("--corpus-dir", type=pathlib.Path, default=DEFAULT_CORPUS)
    parser.add_argument("--output-dir", type=pathlib.Path, required=True)
    parser.add_argument("--agent-id", default="decoder-dav1d-screen")
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    runner = Runner(args)
    try:
        summary = runner.run()
        print(json.dumps({
            "status": "COMPLETE",
            "mode": args.mode,
            "sample_rows": len(runner.rows),
            "summary": str(runner.out / "summary.json"),
            "manifest": str(runner.out / "manifest.json"),
            "case_results": summary["case_results"],
        }, sort_keys=True))
        return 0
    except Exception as exc:
        runner.fail(exc)
        print(f"FAILED_INCOMPLETE: {runner.current_stage}: {exc}", file=sys.stderr, flush=True)
        return 1


if __name__ == "__main__":
